// Block (composition) — a two-factor setup section with secret display and code verification.
// Form controls own behavior/look; this Block only arranges setup content and submission.
import type { FormEvent, ReactNode, Ref } from "react";
import { Alert } from "../components/Alert";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./TwoFactorSetup.css";

export interface TwoFactorSetupProps {
  secret?: string;
  qrCode?: ReactNode;
  heading?: string;
  onVerify?: (code: string) => void;
  isPending?: boolean;
  errorMessage?: string;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function TwoFactorSetup({
  secret,
  qrCode,
  heading = "Two-factor authentication",
  onVerify,
  isPending,
  errorMessage,
  className,
  ref,
}: TwoFactorSetupProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onVerify?.(String(data.get("code") ?? ""));
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-twofactorsetup ${className}` : "sd-twofactorsetup"}
    >
      {/* `large`, because the columns it parts use `small` inside: the secret column and, below 768,
          the code-and-Verify column. At `small` here the secret line sat as close to the code field
          as to its own parts, a ratio of 1.0 in every brand. It matches `InviteForm`'s root. NOT
          from a heading-role ladder: `block-contract.md` §4a records why there is none. */}
      <Stack gap="large" className="sd-twofactorsetup__content">
        {/* The heading and its instructions are ONE unit, so they take their own parent at a rung
            tighter than the section's — `PageHeader` is the reference and uses `x-small` for the
            same section-level pair. Flat among this stack's children, the heading would sit as
            far from its own instructions as they sit from the QR plate: two things reading as three. */}
        <>
          <Stack gap="x-small" className="sd-twofactorsetup__intro">
            {heading && (
              <h2 className="sd-twofactorsetup__heading sd-type-title-medium">{heading}</h2>
            )}
            <p className="sd-twofactorsetup__instructions sd-type-body-medium">
              Scan the QR code with your authenticator app, or enter the setup key manually. Then
              enter the verification code to finish setup.
            </p>
          </Stack>
        </>
        {(qrCode || secret) && (
          <Stack gap="small" align="start" className="sd-twofactorsetup__setup">
            {qrCode && <div className="sd-twofactorsetup__qr-code">{qrCode}</div>}
            {secret && (
              <>
                <span className="sd-twofactorsetup__secret sd-type-code-medium">{secret}</span>
              </>
            )}
          </Stack>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack direction={{ small: "column", medium: "row" }} gap="small" align={{ medium: "end" }} className="sd-twofactorsetup__verify">
          <TextField
            className="sd-twofactorsetup__code"
            name="code"
            label="Verification code"
            inputMode="numeric"
            autoComplete="one-time-code"
            isRequired
          />
          <Button type="submit" variant="primary" isPending={isPending}>
            Verify
          </Button>
        </Stack>
      </Stack>
    </Form>
  );
}

/* TwoFactorSetup.css — .sd-twofactorsetup (Block)
   Arrangement only: caps setup width and lets the verification field fill its row. */
.sd-twofactorsetup {
  width: 100%;
}

.sd-twofactorsetup__heading,
.sd-twofactorsetup__instructions {
  margin: 0;
}

.sd-twofactorsetup__instructions {
  color: var(--sd-color-text-muted);
}

.sd-twofactorsetup__qr-code {
  max-width: 100%;
}

.sd-twofactorsetup__secret {
  max-width: 100%;
  overflow-wrap: anywhere;
}

.sd-twofactorsetup__code {
  flex: 1;
  min-width: 0;
}
